/* From Uiverse.io by JaydipPrajapati1910 - Tags: red, button, hover, play */
.__UIV_SCOPE__ .button {
  width: 140px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 0px 15px;
  background-color: red;
  border-radius: 10px;
  border: none;
  color: white;
  position: relative;
  cursor: pointer;
  font-weight: 900;
  transition-duration: .2s;
}

.__UIV_SCOPE__ .game path {
  color: white;
}

.__UIV_SCOPE__ .button .arrow {
  position: absolute;
  right: 0;
  padding: 0px 5px;
  width: 30px;
  height: 100%;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button:hover,
.__UIV_SCOPE__ .button:focus {
  background-color: black;
  transition-duration: .2s;
}

.__UIV_SCOPE__ .button:hover .arrow {
  animation: slide-right .6s ease-out both;
}
/* arrow animation */
@keyframes slide-right {
  0% {
    transform: translateX(-10px);
    opacity: 0;
  }

  100% {
    transform: translateX(0);
    opacity: 1;
  }
}

.__UIV_SCOPE__ .button:active {
  transform: translate(1px , 1px);
  transition-duration: .2s;
}
